from qteasy import RuleIterator, Parameter

class DemoTiming(RuleIterator):
    def __init__(self):
        super().__init__(pars=[Parameter('period', 20)])
    def realize(self):
        close = self.get_data('close')
        period = self.get_pars()['period']
        return float(close[-1] > close[-period:].mean())
